// Free email providers: leads from these get flagged
const FREE_DOMAINS = [
  'gmail.com', 'googlemail.com', 'gmx.de', 'gmx.net', 'web.de',
  'yahoo.com', 'yahoo.de', 'outlook.com', 'hotmail.com', 't-online.de', 'icloud.com'
];

// Dropdown text -> lower number of the band
const SIZE_MAP = { '1–49': 1, '50–199': 50, '200–499': 200, '500–999': 500, '1,000–2,000': 1000, '2,000+': 2000 };
const HIRES_MAP = { '1–10': 1, '11–50': 11, '51–100': 51, '100+': 100 };

// Turn "https://www.Site.de/jobs" into "site.de"; "n/a" or empty into ""
function cleanDomain(website) {
  const w = (website || '').trim().toLowerCase();
  if (['', 'n/a', '-'].includes(w)) return '';
  return w.replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0];
}

// Read a field from flat test data, or from HubSpot's properties.<name>.value
function get(lead, flatName, hubspotName) {
  return lead[flatName] ?? lead.properties?.[hubspotName]?.value ?? '';
}

return $input.all().map(item => {
  const lead = item.json;

  // 1-7: read and clean the fields
  const email = String(get(lead, 'email', 'email')).trim().toLowerCase();
  const email_domain = email.split('@')[1] || '';
  const website_domain = cleanDomain(get(lead, 'website', 'website'));
  const company_size = get(lead, 'company_size', 'company_size');
  const planned_hires = get(lead, 'planned_hires', 'planned_hires');

  return { json: {
    hubspot_id: lead.vid ?? '',
    email,
    email_domain,
    website_domain,
    first_name: String(get(lead, 'first_name', 'firstname')).trim(),
    last_name: String(get(lead, 'last_name', 'lastname')).trim(),
    job_title: String(get(lead, 'job_title', 'jobtitle')).trim(),
    company_name: String(get(lead, 'company_name', 'company')).trim(),
    country: get(lead, 'country', 'country'),
    company_size,
    planned_hires,
    current_tool: get(lead, 'current_tool', 'current_tool'),
    message: String(get(lead, 'message', 'message')).replace(/\s+/g, ' ').trim(),

    // 8-12: yes/no flags and numbers for the rules step
    is_free_email: FREE_DOMAINS.includes(email_domain),
    domains_match: email_domain !== '' && email_domain === website_domain,
    website_missing: website_domain === '',
    size_min: SIZE_MAP[company_size] || 0,
    hires_min: HIRES_MAP[planned_hires] || 0
  }};
});

// Hard rules, checked in order. The first rule that matches wins.
const RULES = [
  {
    rule_hit: 'spam',
    fit_tier: 'Disqualified',
    reason: l => 'Spam or test submission',
    matches: l => l.email.startsWith('test@') || l.email_domain === 'test.com'
  },
  {
    rule_hit: 'free_email',
    fit_tier: 'Disqualified',
    reason: l => `Free email domain (${l.email_domain})`,
    matches: l => l.is_free_email === true
  },
  {
    rule_hit: 'too_small',
    fit_tier: 'Disqualified',
    reason: l => 'Company has fewer than 50 employees',
    matches: l => l.size_min === 1
  },
  {
    rule_hit: 'outside_region',
    fit_tier: 'Nurture',
    reason: l => 'Country outside DACH and Netherlands',
    matches: l => l.country === 'Other'
  }
];

return $input.all().map(item => {
  const lead = item.json;
  const hit = RULES.find(rule => rule.matches(lead));

  if (hit) {
    // Lead stopped by a rule
    return { json: {
      ...lead,
      fit_tier: hit.fit_tier,
      rule_hit: hit.rule_hit,
      routing_reason: hit.reason(lead),
      status: 'Filtered'
    }};
  }

  // Lead passed all rules and goes on to enrichment
  return { json: {
    ...lead,
    fit_tier: '',
    rule_hit: 'none',
    routing_reason: '',
    status: 'Passed'
  }};
});

// The lead as it was before the Apollo call
const lead = $('Passed?').item.json;

// Apollo's company data (empty if no match)
const org = $json.organization || null;

// Upper end of each company size band from the form
const SIZE_MAX = { 1: 49, 50: 199, 200: 499, 500: 999, 1000: 2000, 2000: Infinity };

let enrichment = {
  enrichment_ok: false,
  industry: '',
  employees_apollo: null,
  funding_stage: '',
  company_description: '',
  size_conflict: false,
  enrichment_note: ''
};

if (org && org.name) {
  const employees = org.estimated_num_employees || null;
  const min = lead.size_min;
  const max = SIZE_MAX[min];

  // Conflict if Apollo's count is far outside the form's size band (50% tolerance)
  const conflict = Boolean(employees && min) && (employees < min * 0.5 || employees > max * 1.5);

  enrichment = {
    enrichment_ok: true,
    industry: org.industry || '',
    employees_apollo: employees,
    funding_stage: org.latest_funding_stage || '',
    company_description: (org.short_description || '').slice(0, 500),
    size_conflict: conflict,
    enrichment_note: 'Matched in Apollo'
  };
} else {
  enrichment.enrichment_note = `No Apollo match for ${lead.website_domain || 'missing website'}`;
}

return { json: { ...lead, ...enrichment, enriched_at: new Date().toISOString() } };

