// Lead data from before the AI Agent
const lead = $('Merge enrichment').item.json;

// The AI Agent's answer is in $json.output. Strip any code fences.
const text = String($json.output || '')
  .replace(/```json|```/g, '')
  .trim();

// Score -> tier bands
function tierFromScore(score) {
  if (score >= 75) return 'A';
  if (score >= 50) return 'B';
  if (score >= 25) return 'C';
  return 'Disqualified';
}

// CHECK 1: is the answer valid JSON? If not, send to the SDR for manual review
let result;
try {
  result = JSON.parse(text);
  if (!result.breakdown) throw new Error('No breakdown in AI answer');
} catch (e) {
  return { json: {
    ...lead,
    scoring_ok: false,
    fit_score: null,
    fit_tier: 'B',
    routing_reason: 'Scoring failed, needs manual review',
    scored_at: new Date().toISOString()
  }};
}

// CHECK 2: recompute the score from the 4 parts, then set the tier from the score
const b = result.breakdown || {};
const clamp = n => Math.max(0, Math.min(25, Number(n) || 0));
const score = clamp(b.buyer_role) + clamp(b.company_fit) + clamp(b.hiring_need) + clamp(b.intent);
let tier = tierFromScore(score);

const notes = [];
if (score !== result.fit_score) notes.push(`Score corrected from ${result.fit_score} to ${score}`);
if (tier !== result.tier) notes.push(`Tier corrected from ${result.tier} to ${tier}`);

// CHECK 3: job seekers and agencies are always disqualified
if (result.is_job_seeker) { tier = 'Disqualified'; notes.push('Override: job seeker'); }
if (result.is_agency) { tier = 'Disqualified'; notes.push('Override: agency or reseller'); }

const reasons = (result.reasons || []).slice(0, 3);

return { json: {
  ...lead,
  scoring_ok: true,
  fit_score: score,
  fit_tier: tier,
  score_breakdown: b,
  reasons,
  routing_reason: reasons.join(' | '),
  is_job_seeker: Boolean(result.is_job_seeker),
  is_agency: Boolean(result.is_agency),
  suggested_opener: result.suggested_opener || '',
  scoring_note: notes.join('; '),
  scored_at: new Date().toISOString()
}};

// Round-robin between the two AEs
const AES = ['Anna (AE)', 'Ben (AE)'];
const memory = $getWorkflowStaticData('global');
const next = ((memory.lastAE ?? -1) + 1) % AES.length;
memory.lastAE = next;

return { json: { ...$json, assigned_rep: AES[next] } };

// Read a HubSpot property value, or '' if missing
const p = name => $json.properties?.[name]?.value ?? '';

// Who gets alerted (replace with real rep addresses)
const REPS = {
  'Anna (AE)':   'anna@example.com',
  'Ben (AE)':    'ben@example.com',
  'Chris (SDR)': 'chris@example.com'
};

// The opener isn't stored in HubSpot, so take it from the parse node.
// Leads filtered by the hard rules never went through it, so fall back to ''.
let opener = '';
try {
  opener = $('Parse + safety checks').item.json.suggested_opener || '';
} catch (e) {}

const rep = p('assigned_rep');

return { json: {
  hubspot_id: $json.vid,
  email: p('email'),
  first_name: p('firstname'),
  last_name: p('lastname'),
  job_title: p('jobtitle'),
  company_name: p('company'),
  fit_tier: p('fit_tier'),
  fit_score: p('fit_score'),
  routing_reason: p('routing_reason'),
  assigned_rep: rep,
  suggested_opener: opener,
  rep_email: REPS[rep] || '',
  alert: Boolean(REPS[rep])   // Nurture has no rep, so no alert
}};

